# (чтение) «Ламинация Автокомп» 07–08.09.2026: движения «Рама 63мм Bauline с сер упл бел 6,5м» по РН ТоварыНаСкладах с остатком.
LAM = q('ВЫБРАТЬ С.Ссылка КАК С ИЗ Справочник.Склады КАК С ГДЕ С.Наименование ПОДОБНО "%Ламинац%" И НЕ С.ЭтоГруппа')[0]['С']
N = q('ВЫБРАТЬ Н.Ссылка КАК С ИЗ Справочник.Номенклатура КАК Н ГДЕ Н.Наименование = "Рама 63мм Bauline с сер упл бел 6,5м"')[0]['С']
d0, d1 = datetime.datetime(2026, 9, 1), datetime.datetime(2026, 9, 9)
ost = q('ВЫБРАТЬ ЕСТЬNULL(СУММА(О.ВНаличииОстаток), 0) КАК К ИЗ РегистрНакопления.ТоварыНаСкладах.Остатки(&Д, Склад = &С И Номенклатура = &Н) КАК О', Д=d0, С=LAM, Н=N)[0]['К']
print('остаток на 01.09.2026:', ost)
for r in q('ВЫБРАТЬ Т.Период КАК П, Т.Регистратор КАК Р, Т.ВидДвижения КАК ВД, Т.ВНаличии КАК К ИЗ РегистрНакопления.ТоварыНаСкладах КАК Т ГДЕ Т.Склад = &С И Т.Номенклатура = &Н И Т.Период МЕЖДУ &А И &Б УПОРЯДОЧИТЬ ПО Т.Период', С=LAM, Н=N, А=d0, Б=d1):
    k = float(r['К']) * (1 if s(r['ВД']) == 'Приход' else -1); ost += k
    print(f"  {str(r['П'])[:16]} {k:+8.1f} → {ost:8.1f} | {s(r['Р'])[:70]}")
